-- GENERATED by scripts/gen-suites.mjs from registry/db-schema.json — TC Treasury circular (PP) central / central panel contract. READ-ONLY queries for DBeaver, SIT connection only.
-- Replace {NO} with the document number (e.g. TC26…). Mapping verified: yes — SIT 2026-11-24: CQ 1010/1011, PQ 1226/1227 doc ids are CT_CIRCULAR_VER.CIRCULAR_VER_ID (the version whose row is current is used); numbers CQ260000000000669

-- Status history (CQ); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.ct_workflow_status w
 where w.doc_type = 'CQ'
   and w.doc_id in (select distinct w.doc_id from ngep_sit.ct_workflow_status w where w.doc_type = 'CQ' and w.is_current = 1 and w.doc_id in (select v.circular_ver_id from ngep_sit.ct_circular_ver v join ngep_sit.ct_circular c on c.circular_id = v.circular_id where c.circular_no = '{NO}'))
 order by w.created_date, w.workflow_status_id;

-- Status history (PQ); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.ct_workflow_status w
 where w.doc_type = 'PQ'
   and w.doc_id in (select distinct w.doc_id from ngep_sit.ct_workflow_status w where w.doc_type = 'PQ' and w.is_current = 1 and w.doc_id in (select v.circular_ver_id from ngep_sit.ct_circular_ver v join ngep_sit.ct_circular c on c.circular_id = v.circular_id where c.circular_no = '{NO}'))
 order by w.created_date, w.workflow_status_id;

-- Open BPM tasks: who the task is assigned to (task name = activityname)
select activityname, state, assignees, acquiredby, to_char(createddate, 'YYYY-MM-DD HH24:MI:SS') as created
  from SIT01_SOAINFRA.wftask@SITSOA
 where customattributestring1 = '{NO}'
 order by createddate;

-- Every status a CQ has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.ct_workflow_status w
 where w.doc_type = 'CQ' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;

-- Every status a PQ has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.ct_workflow_status w
 where w.doc_type = 'PQ' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;
